CREATE TABLE `agent_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息 id',
  `sessionId` bigint NOT NULL COMMENT '会话 id',
  `userId` bigint DEFAULT NULL COMMENT '用户 id（用户消息必填，系统/助手可为空）',
  `role` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色：user/assistant/tool/system',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容（文本或概要）',
  `extra` text COLLATE utf8mb4_unicode_ci COMMENT '额外信息（JSON 字符串，例如搜索模式、ReAct 步骤、图片 id 列表等）',
  `createTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `isDelete` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_sessionId` (`sessionId`),
  KEY `idx_userId` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=69 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent 对话消息';
